def check_m(m):
    # 1. Integrality check: T = m(m+1)/6 must be an integer.
    # This requires m mod 3 != 1
    if m % 3 == 1:
        return False

    T = m * (m + 1) // 6
    A = list(range(1, m + 1))

    # Function to search for Y in the remaining elements A_prime
    def find_Y(A_prime, target_T):

        def dfs_y(index_prime, current_sum_Y, subset_Y):
            if current_sum_Y == target_T and subset_Y:
                return True

            if index_prime == len(A_prime) or current_sum_Y > target_T:
                return False

            element = A_prime[index_prime]

            # Include element
            if dfs_y(index_prime + 1, current_sum_Y + element, subset_Y + [element]):
                return True

            # Exclude element
            if dfs_y(index_prime + 1, current_sum_Y, subset_Y):
                return True

            return False

        return dfs_y(0, 0, [])

    # Function to search for X summing to T, and then check for Y in the remainder
    def find_X(index, current_sum_X, subset_X):
        if current_sum_X == T and subset_X:
            # Found a valid X. Now search for Y in A \ X
            A_prime = [i for i in A if i not in subset_X]

            if find_Y(A_prime, T):
                return True # Found (X, Y) pair
            return False

        if index == m or current_sum_X > T:
            return False

        element = A[index]

        # Include element
        if find_X(index + 1, current_sum_X + element, subset_X + [element]):
            return True

        # Exclude element
        if find_X(index + 1, current_sum_X, subset_X):
            return True

        return False

    # Initial call to find X
    return find_X(0, 0, [])

